#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_SPEED;
layout(color) uniform half4 amzp_COL1;
layout(color) uniform half4 amzp_COL2;
layout(color) uniform half4 amzp_COL3;
uniform float amzp_STAR_FLARE;
uniform float amzp_STARS_VERY_DIST;
uniform float amzp_STARS_DIST;
uniform float amzp_STARS_MED;
uniform float amzp_STARS_CLOSE;
uniform float amzp_GAMMA;
uniform float amzp_NOISE_OVERLAY;



float hash(float2 p){
    p = fract(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise2d(float2 p){
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash(i);
    float b = hash(i + float2(1.0, 0.0));
    float c = hash(i + float2(0.0, 1.0));
    float d = hash(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float3 nebula(float2 uv){
    float t = time * amzp_SPEED;
    float3 col1 = amzp_COL1.rgb;
    float3 col2 = amzp_COL2.rgb;
    float3 col3 = amzp_COL3.rgb;

    float2 uv1 = uv * 2.0 + t;
    float2 uv2 = uv * 4.0 - t * 1.5;

    float n1 = noise2d(uv1);
    float n2 = noise2d(uv2);
    float finalNoise = n1 * 0.6 + n2 * 0.4;

    float3 color = mix(col1, col2, finalNoise);
    color = mix(color, col3, noise2d(uv * 3.0 + t * 0.7));
    return color;
}

float starCore(float2 uv, float flare, float depth){
    float d = max(abs(uv.x), abs(uv.y));
    float m = (0.02 * depth) / max(d, 1e-4);

    float rayScale = min(screen.zw.x, screen.zw.y) / 1000.0;
    float rayDensity = mix(200.0, 400.0, clamp(rayScale, 0.0, 1.0));

    float rays = max(0.0, 1.0 - abs(uv.x * uv.y * rayDensity));
    rays = smoothstep(0.0, 1.0, rays);
    m += rays * flare * depth * 1.5;
    return m;
}

void amzRender(){
    float2 R = screen.zw;
    float2 frag = amzScreenNorm() * R;
    float2 uv = (frag - 0.5 * R) / max(R.y, 1.0);

    float3 color = nebula(uv);

    float amzLocal_time = time * 0.2;
    float timeSlowA = amzLocal_time * 0.02;
    float timeSlowB = amzLocal_time * 0.05;
    float timeSlowC = amzLocal_time * 0.1;
    float timeSlowD = amzLocal_time * 0.15;

    int vcnt = int(clamp(amzp_STARS_VERY_DIST, 0.0, 32.0));
    int dcnt = int(clamp(amzp_STARS_DIST, 0.0, 32.0));
    int mcnt = int(clamp(amzp_STARS_MED, 0.0, 32.0));
    int ccnt = int(clamp(amzp_STARS_CLOSE, 0.0, 32.0));
    float flare = amzp_STAR_FLARE;


    for (int i = 0; i < 32; i++){
        if (i >= vcnt) break;
        float ii = float(i) * 0.3;
        float2 starPos = float2(
            noise2d(float2(ii, timeSlowA)),
            noise2d(float2(ii + 42.0, timeSlowA))
        ) * 2.0 - 1.0;
        float depth = 0.1 + hash(float2(float(i) * 2.0, 0.0)) * 0.1;
        color += float3(0.6, 0.6, 0.7) * starCore(uv - starPos, 0.5 * flare, depth) * (0.2 + 0.2 * sin(amzLocal_time + float(i)));
    }


    for (int i = 0; i < 32; i++){
        if (i >= dcnt) break;
        float ii = float(i) * 0.5;
        float2 starPos = float2(
            noise2d(float2(ii, timeSlowB)),
            noise2d(float2(ii + 42.0, timeSlowB))
        ) * 2.0 - 1.0;
        float depth = 0.3 + hash(float2(float(i) * 2.0, 0.0)) * 0.2;
        color += float3(0.8, 0.7, 0.6) * starCore(uv - starPos, 0.8 * flare, depth) * (0.3 + 0.3 * sin(amzLocal_time + float(i)));
    }


    for (int i = 0; i < 32; i++){
        if (i >= mcnt) break;
        float ii = (float(i) + 5.0) * 0.7;
        float2 starPos = float2(
            noise2d(float2(ii, timeSlowC)),
            noise2d(float2(ii + 42.0, timeSlowC))
        ) * 2.0 - 1.0;
        float depth = 0.6 + hash(float2((float(i) + 5.0) * 2.0, 0.0)) * 0.2;
        color += float3(0.9, 0.8, 0.7) * starCore(uv - starPos, 1.0 * flare, depth) * (0.4 + 0.4 * sin(amzLocal_time + float(i)));
    }


    for (int i = 0; i < 32; i++){
        if (i >= ccnt) break;
        float idx = float(i) + 8.0;
        float2 starPos = float2(
            noise2d(float2(idx, timeSlowD)),
            noise2d(float2(idx + 42.0, timeSlowD))
        ) * 2.0 - 1.0;
        float depth = 0.9 + hash(float2(idx * 2.0, 0.0)) * 0.2;
        color += float3(1.0, 0.9, 0.8) * starCore(uv - starPos, 1.2 * flare, depth) * (0.5 + 0.5 * sin(amzLocal_time + idx));
    }

    color += float3(hash(uv * 50.0 + amzLocal_time)) * amzp_NOISE_OVERLAY;

    color = pow(max(color, 0.0), float3(amzp_GAMMA));
    color = clamp(color, 0.0, 1.0);

    amzOutput = float4(color, 1.0);
}

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

